naieve//dim3 blockDim(32, 32);//dim3 gridDim(CEIL_DIV(N, 32), CEIL_DIV(M, 32));//mysgemm_v1&lt;&lt;&lt;gridDim, blockDim&gt;&gt;&gt;(M, N, K, alpha, dA, dB, beta, dC_gpu);__global__ __launch_bounds__(1024) voidmysgemm_v1(int M, int N, int K, float alpha, float *A, float *B, float beta, float *C) {    int gx = blockIdx.x * blockDim.x + threadIdx.x; // 全局x    int gy = blockIdx.y * blockDim.y + threadIdx.y; // 全局y    float tmp = 0.0f;    for (int i = 0; i &lt; K; i++) {        tmp += A[gy * K + i] * B[i * N + gx]; // 两次全局内存访问和一次FMA（累加乘）    }    C[gy * N + gx] = alpha * tmp + beta * C[gy * N + gx];}



share_mem + 1 thread process N points#define OFFSET(row, col, ld) ((row) * (ld) + (col))#define FLOAT4(pointer) (reinterpret_cast&lt;float4*&gt;(&amp;(pointer))[0])__global__ void mySgemmV1Aligned(    float * __restrict__ a, float * __restrict__ b, float * __restrict__ c,    const int M, const int N, const int K) {    const int BM = 128;    const int BN = 128;    const int BK = 8;    const int TM = 8;    const int TN = 8;    const int bx = blockIdx.x;    const int by = blockIdx.y;    const int tx = threadIdx.x;    const int ty = threadIdx.y;    const int tid = ty * blockDim.x + tx;    __shared__ float s_a[BM][BK];    __shared__ float s_b[BK][BN];    float r_c[TM][TN] = {0.0};    int load_a_smem_m = tid &gt;&gt; 1;    int load_a_smem_k = (tid &amp; 1) &lt;&lt; 2;    int load_b_smem_k = tid &gt;&gt; 5;    int load_b_smem_n = (tid &amp; 31) &lt;&lt; 2;    int load_a_gmem_m = by * BM + load_a_smem_m;    int load_b_gmem_n = bx * BN + load_b_smem_n;    for (int bk = 0; bk &lt; (K + BK - 1) / BK; bk++) {        int load_a_gmem_k = bk * BK + load_a_smem_k;        int load_a_gmem_addr = OFFSET(load_a_gmem_m, load_a_gmem_k, K);        FLOAT4(s_a[load_a_smem_m][load_a_smem_k]) = FLOAT4(a[load_a_gmem_addr]);        int load_b_gmem_k = bk * BK + load_b_smem_k;        int load_b_gmem_addr = OFFSET(load_b_gmem_k, load_b_gmem_n, N);        FLOAT4(s_b[load_b_smem_k][load_b_smem_n]) = FLOAT4(b[load_b_gmem_addr]);        __syncthreads();        #pragma unroll        for (int k = 0; k &lt; BK; k++) {            #pragma unroll            for (int m = 0; m &lt; TM; m++) {                #pragma unroll                for (int n = 0; n &lt; TN; n++) {                    int comp_a_smem_m = ty * TM + m;                    int comp_b_smem_n = tx * TN + n;                    r_c[m][n] += s_a[comp_a_smem_m][k] * s_b[k][comp_b_smem_n];                }            }        }        __syncthreads();    }    #pragma unroll    for (int i = 0; i &lt; TM; i++) {        int store_c_gmem_m = by * BM + ty * TM + i;        #pragma unroll        for (int j = 0; j &lt; TN; j += 4) {            int store_c_gmem_n = bx * BN + tx * TN + j;            int store_c_gmem_addr = OFFSET(store_c_gmem_m, store_c_gmem_n, N);            FLOAT4(c[store_c_gmem_addr]) = FLOAT4(r_c[i][j]);        }    }}



Fix bank conflict__global__ void mySgemmV2Aligned(    float * __restrict__ a, float * __restrict__ b, float * __restrict__ c,    const int M, const int N, const int K) {    const int BM = 128;    const int BN = 128;    const int BK = 8;    const int TM = 8;    const int TN = 8;    const int bx = blockIdx.x;    const int by = blockIdx.y;    const int tx = threadIdx.x;    const int ty = threadIdx.y;    const int tid = ty * blockDim.x + tx;    __shared__ float s_a[BK][BM];    __shared__ float s_b[BK][BN];    float r_load_a[4];    float r_load_b[4];    float r_comp_a[TM];    float r_comp_b[TN];    float r_c[TM][TN] = {0.0};    int load_a_smem_m = tid &gt;&gt; 1;    int load_a_smem_k = (tid &amp; 1) &lt;&lt; 2;    int load_b_smem_k = tid &gt;&gt; 5;    int load_b_smem_n = (tid &amp; 31) &lt;&lt; 2;    int load_a_gmem_m = by * BM + load_a_smem_m;    int load_b_gmem_n = bx * BN + load_b_smem_n;    for (int bk = 0; bk &lt; (K + BK - 1) / BK; bk++) {        int load_a_gmem_k = bk * BK + load_a_smem_k;        int load_a_gmem_addr = OFFSET(load_a_gmem_m, load_a_gmem_k, K);        int load_b_gmem_k = bk * BK + load_b_smem_k;        int load_b_gmem_addr = OFFSET(load_b_gmem_k, load_b_gmem_n, N);        FLOAT4(r_load_a[0]) = FLOAT4(a[load_a_gmem_addr]);        FLOAT4(r_load_b[0]) = FLOAT4(b[load_b_gmem_addr]);        s_a[load_a_smem_k    ][load_a_smem_m] = r_load_a[0];        s_a[load_a_smem_k + 1][load_a_smem_m] = r_load_a[1];        s_a[load_a_smem_k + 2][load_a_smem_m] = r_load_a[2];        s_a[load_a_smem_k + 3][load_a_smem_m] = r_load_a[3];        FLOAT4(s_b[load_b_smem_k][load_b_smem_n]) = FLOAT4(r_load_b[0]);        __syncthreads();        #pragma unroll        for (int tk = 0; tk &lt; BK; tk++) {            FLOAT4(r_comp_a[0]) = FLOAT4(s_a[tk][ty * TM / 2         ]);            FLOAT4(r_comp_a[4]) = FLOAT4(s_a[tk][ty * TM / 2 + BM / 2]);            FLOAT4(r_comp_b[0]) = FLOAT4(s_b[tk][tx * TN / 2         ]);            FLOAT4(r_comp_b[4]) = FLOAT4(s_b[tk][tx * TN / 2 + BN / 2]);            #pragma unroll            for (int tm = 0; tm &lt; TM; tm++) {                #pragma unroll                for (int tn = 0; tn &lt; TN; tn++) {                    r_c[tm][tn] += r_comp_a[tm] * r_comp_b[tn];                }            }        }        __syncthreads();    }    #pragma unroll    for (int i = 0; i &lt; TM / 2; i++) {        int store_c_gmem_m = by * BM + ty * TM / 2 + i;        int store_c_gmem_n = bx * BN + tx * TN / 2;        int store_c_gmem_addr = OFFSET(store_c_gmem_m, store_c_gmem_n, N);        FLOAT4(c[store_c_gmem_addr]) = FLOAT4(r_c[i][0]);        FLOAT4(c[store_c_gmem_addr + BN / 2]) = FLOAT4(r_c[i][4]);    }    #pragma unroll    for (int i = 0; i &lt; TM / 2; i++) {        int store_c_gmem_m = by * BM + BM / 2 + ty * TM / 2 + i;        int store_c_gmem_n = bx * BN + tx * TN / 2;        int store_c_gmem_addr = OFFSET(store_c_gmem_m, store_c_gmem_n, N);        FLOAT4(c[store_c_gmem_addr]) = FLOAT4(r_c[i + TM / 2][0]);        FLOAT4(c[store_c_gmem_addr + BN / 2]) = FLOAT4(r_c[i + TM / 2][4]);    }}



double buffer__global__ void mySgemmV3Aligned(    float * __restrict__ a, float * __restrict__ b, float * __restrict__ c,    const int M, const int N, const int K) {    const int BM = 128;    const int BN = 128;    const int BK = 8;    const int TM = 8;    const int TN = 8;    const int bx = blockIdx.x;    const int by = blockIdx.y;    const int tx = threadIdx.x;    const int ty = threadIdx.y;    const int tid = ty * blockDim.x + tx;    __shared__ float s_a[2][BK][BM];    __shared__ float s_b[2][BK][BN];    float r_load_a[4];    float r_load_b[4];    float r_comp_a[TM];    float r_comp_b[TN];    float r_c[TM][TN] = {0.0};    int load_a_smem_m = tid &gt;&gt; 1;    int load_a_smem_k = (tid &amp; 1) &lt;&lt; 2;    int load_b_smem_k = tid &gt;&gt; 5;    int load_b_smem_n = (tid &amp; 31) &lt;&lt; 2;    int load_a_gmem_m = by * BM + load_a_smem_m;    int load_b_gmem_n = bx * BN + load_b_smem_n;    {        int load_a_gmem_k = load_a_smem_k;        int load_a_gmem_addr = OFFSET(load_a_gmem_m, load_a_gmem_k, K);        int load_b_gmem_k = load_b_smem_k;        int load_b_gmem_addr = OFFSET(load_b_gmem_k, load_b_gmem_n, N);        FLOAT4(r_load_a[0]) = FLOAT4(a[load_a_gmem_addr]);        FLOAT4(r_load_b[0]) = FLOAT4(b[load_b_gmem_addr]);        s_a[0][load_a_smem_k    ][load_a_smem_m] = r_load_a[0];        s_a[0][load_a_smem_k + 1][load_a_smem_m] = r_load_a[1];        s_a[0][load_a_smem_k + 2][load_a_smem_m] = r_load_a[2];        s_a[0][load_a_smem_k + 3][load_a_smem_m] = r_load_a[3];        FLOAT4(s_b[0][load_b_smem_k][load_b_smem_n]) = FLOAT4(r_load_b[0]);    }    for (int bk = 1; bk &lt; (K + BK - 1) / BK; bk++) {        __syncthreads();        int smem_sel = (bk - 1) &amp; 1;        int smem_sel_next = bk &amp; 1;        int load_a_gmem_k = bk * BK + load_a_smem_k;        int load_a_gmem_addr = OFFSET(load_a_gmem_m, load_a_gmem_k, K);        int load_b_gmem_k = bk * BK + load_b_smem_k;        int load_b_gmem_addr = OFFSET(load_b_gmem_k, load_b_gmem_n, N);        FLOAT4(r_load_a[0]) = FLOAT4(a[load_a_gmem_addr]);        FLOAT4(r_load_b[0]) = FLOAT4(b[load_b_gmem_addr]);        #pragma unroll        for (int tk = 0; tk &lt; BK; tk++) {            FLOAT4(r_comp_a[0]) = FLOAT4(s_a[smem_sel][tk][ty * TM / 2         ]);            FLOAT4(r_comp_a[4]) = FLOAT4(s_a[smem_sel][tk][ty * TM / 2 + BM / 2]);            FLOAT4(r_comp_b[0]) = FLOAT4(s_b[smem_sel][tk][tx * TN / 2         ]);            FLOAT4(r_comp_b[4]) = FLOAT4(s_b[smem_sel][tk][tx * TN / 2 + BN / 2]);            #pragma unroll            for (int tm = 0; tm &lt; TM; tm++) {                #pragma unroll                for (int tn = 0; tn &lt; TN; tn++) {                    r_c[tm][tn] += r_comp_a[tm] * r_comp_b[tn];                }            }        }        s_a[smem_sel_next][load_a_smem_k    ][load_a_smem_m] = r_load_a[0];        s_a[smem_sel_next][load_a_smem_k + 1][load_a_smem_m] = r_load_a[1];        s_a[smem_sel_next][load_a_smem_k + 2][load_a_smem_m] = r_load_a[2];        s_a[smem_sel_next][load_a_smem_k + 3][load_a_smem_m] = r_load_a[3];        FLOAT4(s_b[smem_sel_next][load_b_smem_k][load_b_smem_n]) = FLOAT4(r_load_b[0]);            }    __syncthreads();    #pragma unroll    for (int tk = 0; tk &lt; BK; tk++) {        FLOAT4(r_comp_a[0]) = FLOAT4(s_a[smem_sel_next][tk][ty * TM / 2         ]);        FLOAT4(r_comp_a[4]) = FLOAT4(s_a[smem_sel_next][tk][ty * TM / 2 + BM / 2]);        FLOAT4(r_comp_b[0]) = FLOAT4(s_b[smem_sel_next][tk][tx * TN / 2         ]);        FLOAT4(r_comp_b[4]) = FLOAT4(s_b[smem_sel_next][tk][tx * TN / 2 + BN / 2]);        #pragma unroll        for (int tm = 0; tm &lt; TM; tm++) {            #pragma unroll            for (int tn = 0; tn &lt; TN; tn++) {                r_c[tm][tn] += r_comp_a[tm] * r_comp_b[tn];            }        }    }    #pragma unroll    for (int i = 0; i &lt; TM / 2; i++) {        int store_c_gmem_m = by * BM + ty * TM / 2 + i;        int store_c_gmem_n = bx * BN + tx * TN / 2;        int store_c_gmem_addr = OFFSET(store_c_gmem_m, store_c_gmem_n, N);        FLOAT4(c[store_c_gmem_addr]) = FLOAT4(r_c[i][0]);        FLOAT4(c[store_c_gmem_addr + BN / 2]) = FLOAT4(r_c[i][4]);    }    #pragma unroll    for (int i = 0; i &lt; TM / 2; i++) {        int store_c_gmem_m = by * BM + BM / 2 + ty * TM / 2 + i;        int store_c_gmem_n = bx * BN + tx * TN / 2;        int store_c_gmem_addr = OFFSET(store_c_gmem_m, store_c_gmem_n, N);        FLOAT4(c[store_c_gmem_addr]) = FLOAT4(r_c[i + TM / 2][0]);        FLOAT4(c[store_c_gmem_addr + BN / 2]) = FLOAT4(r_c[i + TM / 2][4]);    }}

