Naievetemplate &lt;int BLOCK_DIM_X, int BLOCK_DIM_Y&gt;__global__ void transpose_v1(int M, int N,                  //                             const float *__restrict__ iA,  //                             float *__restrict__ oA) {  const int y = blockIdx.y * BLOCK_DIM_Y + threadIdx.y;  const int x = blockIdx.x * BLOCK_DIM_X + threadIdx.x;  if (y &gt;= N || x &gt;= M) {    return;  }  oA[y * M + x] = iA[x * N + y];}

Shared memtemplate &lt;int BLOCK_DIM_X, int BLOCK_DIM_Y&gt;__global__ void transpose_v2_32x32(int M, int N,                  //                                   const float *__restrict__ iA,  //                                   float *__restrict__ oA) {  __shared__ float smem[32][32];  // Global Memory -&gt; Shared Memory  {    constexpr const int ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const int ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = blockIdx.x * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = blockIdx.y * 32 + lx;        if (gy &lt; M &amp;&amp; gx &lt; N) {          smem[lx][ly] = iA[gy * N + gx];        }      }    }  }  __syncthreads();  // Shared Memory -&gt; Global Memory  {    constexpr const auto ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const auto ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = blockIdx.y * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = blockIdx.x * 32 + lx;        if (gy &lt; N &amp;&amp; gx &lt; M) {          oA[gy * M + gx] = smem[ly][lx];        }      }    }  }}



Fix Bank conflicttemplate &lt;int BLOCK_DIM_X, int BLOCK_DIM_Y&gt;__global__ void transpose_v3_32x32(int M, int N,                  //                                   const float *__restrict__ iA,  //                                   float *__restrict__ oA) {  __shared__ float smem[32][32];  // Global Memory -&gt; Shared Memory  {    constexpr const int ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const int ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = blockIdx.x * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = blockIdx.y * 32 + lx;        if (gy &lt; M &amp;&amp; gx &lt; N) {          smem[lx][(lx + ly) % 32] = iA[gy * N + gx];        }      }    }  }  __syncthreads();  // Shared Memory -&gt; Global Memory  {    constexpr const auto ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const auto ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = blockIdx.y * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = blockIdx.x * 32 + lx;        if (gy &lt; N &amp;&amp; gx &lt; M) {          oA[gy * M + gx] = smem[ly][(lx + ly) % 32];        }      }    }  }}

double buffertemplate &lt;int ITER_BLOCK_X, int ITER_BLOCK_Y,  //          int BLOCK_DIM_X, int BLOCK_DIM_Y&gt;__global__ void transpose_v4_32x32(int M, int N,                  //                                   const float *__restrict__ iA,  //                                   float *__restrict__ oA) {  __shared__ float smem[2][32][32];  auto MoveG2S = [&amp;](int i) {    constexpr const int ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const int ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);    const int by = i / ITER_BLOCK_X * gridDim.y + blockIdx.y;    const int bx = i % ITER_BLOCK_X * gridDim.x + blockIdx.x;#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = bx * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = by * 32 + lx;        if (gy &lt; M &amp;&amp; gx &lt; N) {          smem[i &amp; 1][lx][(lx + ly) % 32] = iA[gy * N + gx];        }      }    }  };  auto MoveS2G = [&amp;](int i) {    constexpr const auto ITER_Y = 32 / BLOCK_DIM_Y;    constexpr const auto ITER_X = 32 / BLOCK_DIM_X;    static_assert(ITER_Y * BLOCK_DIM_Y == 32);    static_assert(ITER_X * BLOCK_DIM_X == 32);    const int by = i / ITER_BLOCK_X * gridDim.y + blockIdx.y;    const int bx = i % ITER_BLOCK_X * gridDim.x + blockIdx.x;#pragma unroll    for (int iy = 0; iy &lt; ITER_Y; iy++) {      const int ly = iy * BLOCK_DIM_Y + threadIdx.x / BLOCK_DIM_X;      const int gy = by * 32 + ly;#pragma unroll      for (int ix = 0; ix &lt; ITER_X; ix++) {        const int lx = ix * BLOCK_DIM_X + threadIdx.x % BLOCK_DIM_X;        const int gx = bx * 32 + lx;        if (gy &lt; N &amp;&amp; gx &lt; M) {          oA[gy * M + gx] = smem[i &amp; 1][ly][(lx + ly) % 32];        }      }    }  };  MoveG2S(0);#pragma unroll  for (int i = 0; i &lt; ITER_BLOCK_Y * ITER_BLOCK_X; i++) {    __syncthreads();    if (i + 1 &lt; ITER_BLOCK_Y * ITER_BLOCK_X) {      MoveG2S(i + 1);    }    MoveS2G(i);  }}
